from app.db.session import SessionLocal
from sqlalchemy import text
db = SessionLocal()
db.execute(text("SET TRANSACTION READ ONLY")); db.execute(text("SET LOCAL statement_timeout = 60000"))
exec("def _fmt(k, v):\n    if k.startswith('u_') and isinstance(v, int) and 0 < v < 5:\n        return '<5'\n    return v\n")
exec("def q(title, sql):\n    print('=== ' + title + ' ===')\n    try:\n        rows = db.execute(text(sql)).fetchall()\n        for r in rows:\n            print(' | '.join(f'{k}={_fmt(k, v)}' for k, v in r._mapping.items()))\n    except Exception as e:\n        print('QERR', type(e).__name__, str(e).splitlines()[0][:300])\n        db.rollback()\n        db.execute(text('SET TRANSACTION READ ONLY'))\n        db.execute(text('SET LOCAL statement_timeout = 60000'))\n")
B = "WITH base AS (SELECT tc.user_id, tc.created_at AS t_start, tc.updated_at AS t_upd, CASE WHEN tc.updated_at IS NOT NULL AND tc.updated_at - tc.created_at <= interval '3 hours' THEN tc.updated_at ELSE tc.created_at END AS t_done, tc.focus_areas, tc.severity_ratings, tc.goals_text, (coalesce(u.email,'') ILIKE 'test%' OR coalesce(u.email,'') ILIKE '%+test%' OR coalesce(u.email,'') ILIKE '%test@%' OR coalesce(u.email,'') ILIKE '%tester%' OR coalesce(u.email,'') ILIKE '%@mindsync.%' OR coalesce(u.email,'') ILIKE '%@example.%') AS testish, CASE WHEN p.time_zone IN (SELECT name FROM pg_timezone_names) THEN p.time_zone ELSE 'UTC' END AS tz, coalesce(p.time_zone IN (SELECT name FROM pg_timezone_names), false) AS tz_valid, p.therapy_schedule, p.custom_therapy_sessions, p.therapy_frequency, pr.currently_in_therapy AS cit FROM user_therapy_context tc JOIN users u ON u.id = tc.user_id LEFT JOIN user_preferences p ON p.user_id = tc.user_id LEFT JOIN user_profile pr ON pr.user_id = tc.user_id WHERE tc.onboarding_completed = true), c AS (SELECT * FROM base WHERE NOT testish AND t_done >= now() - interval 'DAYS days')"
cohort = lambda d: B.replace("DAYS", str(d))
q("s0_alembic", "SELECT version_num FROM alembic_version")
q("s0_columns", "SELECT table_name, column_name, data_type FROM information_schema.columns WHERE table_schema='public' AND (table_name, column_name) IN (('user_therapy_context','focus_areas'),('user_therapy_context','severity_ratings'),('user_therapy_context','goals_text'),('user_therapy_context','onboarding_completed'),('user_therapy_context','updated_at'),('user_preferences','therapy_schedule'),('user_preferences','custom_therapy_sessions'),('user_preferences','time_zone'),('user_preferences','therapy_frequency'),('user_profile','currently_in_therapy'),('conversations','entry_origin'),('conversations','last_message_at'),('user_memory_items','category'),('user_memory_items','source'),('session_prep_cards','generation_type'),('user_goals','created_at')) ORDER BY 1,2")
q("s0_enums", "SELECT t.typname, string_agg(e.enumlabel, ',' ORDER BY e.enumsortorder) AS labels FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid WHERE t.typname IN ('conversationtypeenum','inputtypeenum') GROUP BY 1")
q("s1_sizes", cohort(90) + " SELECT count(*) FILTER (WHERE t_done >= now() - interval '90 days') AS u_completed90_incl_test, count(*) FILTER (WHERE testish AND t_done >= now() - interval '90 days') AS u_testish90, (SELECT count(*) FROM c) AS u_cohort90, count(*) FILTER (WHERE NOT testish AND t_done >= now() - interval '30 days') AS u_cohort30, count(*) FILTER (WHERE testish AND t_done >= now() - interval '30 days') AS u_testish30, count(*) AS u_completed_alltime, count(DISTINCT user_id) AS u_distinct_alltime FROM base")
q("s1_started_not_completed_90", "SELECT count(*) AS u_started_not_completed90 FROM user_therapy_context WHERE onboarding_completed = false AND created_at >= now() - interval '90 days'")
q("s1_gap_start_to_update_90", cohort(90) + " SELECT CASE WHEN t_upd - t_start <= interval '10 minutes' THEN 'a_le10m' WHEN t_upd - t_start <= interval '1 hour' THEN 'b_10-60m' WHEN t_upd - t_start <= interval '3 hours' THEN 'c_1-3h' WHEN t_upd - t_start <= interval '1 day' THEN 'd_3-24h' ELSE 'e_gt24h' END AS gap, count(*) AS u_users FROM c GROUP BY 1 ORDER BY 1")
q("s1_weekly_90", cohort(90) + " SELECT to_char(date_trunc('week', t_done), 'YYYY-MM-DD') AS week, count(*) AS u_users FROM c GROUP BY 1 ORDER BY 1")
q("s1_starter_bio_90", cohort(90) + " , b AS (SELECT user_id, min(created_at) AS first_bio FROM personal_bios WHERE user_id IN (SELECT user_id FROM c) GROUP BY user_id) SELECT count(*) AS u_with_bio, percentile_cont(0.5) WITHIN GROUP (ORDER BY extract(epoch FROM (b.first_bio - c.t_start)) / 60.0) AS median_min_start_to_bio, percentile_cont(0.5) WITHIN GROUP (ORDER BY extract(epoch FROM (b.first_bio - c.t_done)) / 60.0) AS median_min_done_to_bio FROM c JOIN b ON b.user_id = c.user_id")
F = " , f AS (SELECT user_id, CASE WHEN left(btrim(coalesce(focus_areas,'')),1) = '[' THEN jsonb_array_length(focus_areas::jsonb) ELSE 0 END AS n FROM c)"
E = " , e AS (SELECT c.user_id, x AS el FROM c, jsonb_array_elements(CASE WHEN left(btrim(coalesce(c.focus_areas,'')),1) = '[' THEN c.focus_areas::jsonb ELSE '[]'::jsonb END) x)"
_ = [q(f"q1_focus_count_dist_{d}", cohort(d) + F + " SELECT CASE WHEN n >= 6 THEN '6+' ELSE n::text END AS n_areas, count(*) AS u_users FROM f GROUP BY 1 ORDER BY 1") for d in (90, 30)]
_ = [q(f"q1_focus_count_stats_{d}", cohort(d) + F + " SELECT count(*) AS u_users, percentile_cont(0.5) WITHIN GROUP (ORDER BY n) AS median_n, round(avg(n), 2) AS mean_n, percentile_cont(0.5) WITHIN GROUP (ORDER BY n) FILTER (WHERE n > 0) AS median_n_nonzero FROM f") for d in (90, 30)]
_ = [q(f"q1_custom_{d}", cohort(d) + E + " SELECT count(DISTINCT user_id) AS u_with_any_area, count(DISTINCT user_id) FILTER (WHERE el->>'is_custom' = 'true') AS u_with_custom, count(*) FILTER (WHERE el->>'is_custom' = 'true') AS u_custom_areas_total, count(*) FILTER (WHERE el->>'is_custom' = 'false') AS n_preset_areas_total, count(*) FILTER (WHERE el->>'is_custom' IS NULL) AS u_areas_missing_flag FROM e") for d in (90, 30)]
_ = [q(f"q1_top10_preset_labels_{d}", cohort(d) + E + " SELECT coalesce(el->>'name', el->>'label') AS label, count(DISTINCT user_id) AS u_users FROM e WHERE el->>'is_custom' = 'false' GROUP BY 1 ORDER BY 2 DESC LIMIT 10") for d in (90, 30)]
_ = [q(f"q1_xcheck_user_symptoms_{d}", cohort(d) + " , sy AS (SELECT c.user_id, count(s.id) AS n, count(s.id) FILTER (WHERE s.is_custom) AS n_custom FROM c LEFT JOIN user_symptoms s ON s.user_id = c.user_id AND s.created_at >= c.t_start - interval '1 minute' AND s.created_at <= c.t_done + interval '1 hour' GROUP BY c.user_id) SELECT CASE WHEN n >= 6 THEN '6+' ELSE n::text END AS n_symptoms, count(*) AS u_users, count(*) FILTER (WHERE n_custom > 0) AS u_with_custom FROM sy GROUP BY 1 ORDER BY 1") for d in (90, 30)]
R = " , r AS (SELECT c.user_id, kv.value AS v FROM c, jsonb_each_text(CASE WHEN left(btrim(coalesce(c.severity_ratings,'')),1) = '{' THEN c.severity_ratings::jsonb ELSE '{}'::jsonb END) kv WHERE kv.value ~ '^[0-9]+([.][0-9]+)?$')"
_ = [q(f"q2_severity_stats_{d}", cohort(d) + R + " SELECT count(*) AS n_ratings, count(DISTINCT user_id) AS u_users, min(v::numeric) AS min_v, percentile_cont(0.5) WITHIN GROUP (ORDER BY v::numeric) AS median_v, max(v::numeric) AS max_v, round(avg(v::numeric), 2) AS mean_v FROM r") for d in (90, 30)]
_ = [q(f"q2_severity_hist_{d}", cohort(d) + R + " SELECT round(v::numeric)::int AS score, count(*) AS u_ratings FROM r GROUP BY 1 ORDER BY 1") for d in (90, 30)]
_ = [q(f"q2_severity_per_user_{d}", cohort(d) + R + " , pu AS (SELECT user_id, avg(v::numeric) AS m, max(v::numeric) AS mx FROM r GROUP BY user_id) SELECT count(*) AS u_users, percentile_cont(0.5) WITHIN GROUP (ORDER BY m) AS median_user_mean, percentile_cont(0.5) WITHIN GROUP (ORDER BY mx) AS median_user_max FROM pu") for d in (90, 30)]
_ = [q(f"q2_first_symptom_score_{d}", cohort(d) + " , fs AS (SELECT DISTINCT ON (s.symptom_id) s.user_id, s.score FROM c JOIN symptom_scores s ON s.user_id = c.user_id AND s.created_at >= c.t_start - interval '1 minute' AND s.created_at <= c.t_done + interval '1 hour' ORDER BY s.symptom_id, s.created_at) SELECT count(*) AS n_scores, count(DISTINCT user_id) AS u_users, min(score) AS min_s, percentile_cont(0.5) WITHIN GROUP (ORDER BY score) AS median_s, max(score) AS max_s, round(avg(score), 2) AS mean_s FROM fs") for d in (90, 30)]
_ = [q(f"q3_therapy_status_{d}", cohort(d) + " SELECT coalesce(cit, '(null)') AS status, count(*) AS u_users FROM c GROUP BY 1 ORDER BY 2 DESC") for d in (90, 30)]
_ = [q(f"q3_status_vs_art9_{d}", cohort(d) + " , a9 AS (SELECT DISTINCT user_id FROM consent_records WHERE consent_type = 'ARTICLE9_HEALTH' AND withdrawn_at IS NULL) SELECT (c.cit IS NOT NULL) AS has_status, (a9.user_id IS NOT NULL) AS art9_active, count(*) AS u_users FROM c LEFT JOIN a9 ON a9.user_id = c.user_id GROUP BY 1, 2 ORDER BY 1, 2") for d in (90, 30)]
S = " , s AS (SELECT c.*, CASE WHEN left(btrim(coalesce(therapy_schedule,'')),1) = '[' THEN jsonb_array_length(therapy_schedule::jsonb) ELSE 0 END AS ns, CASE WHEN left(btrim(coalesce(custom_therapy_sessions,'')),1) = '[' THEN jsonb_array_length(custom_therapy_sessions::jsonb) ELSE 0 END AS nc FROM c)"
_ = [q(f"q4_schedule_by_status_{d}", cohort(d) + S + " SELECT coalesce(cit, '(null)') AS status, count(*) AS u_users, count(*) FILTER (WHERE ns > 0 OR nc > 0) AS u_sched_any, count(*) FILTER (WHERE ns > 0) AS u_recurring, count(*) FILTER (WHERE nc > 0) AS u_custom_dates FROM s GROUP BY 1 ORDER BY 2 DESC") for d in (90, 30)]
_ = [q(f"q4_frequency_in_therapy_with_sched_{d}", cohort(d) + S + " SELECT coalesce(therapy_frequency, '(null)') AS freq, count(*) AS u_users FROM s WHERE cit IN ('yes_regular','yes_occasional') AND (ns > 0 OR nc > 0) GROUP BY 1 ORDER BY 2 DESC") for d in (90, 30)]
q("q4_schedule_entry_format_90", cohort(90) + " , e AS (SELECT x FROM c, jsonb_array_elements(CASE WHEN left(btrim(coalesce(c.therapy_schedule,'')),1) = '[' THEN c.therapy_schedule::jsonb ELSE '[]'::jsonb END) x) SELECT jsonb_typeof(x->'day_of_week') AS dow_type, coalesce((x->>'day_of_week') ~ '^[0-6]$', false) AS dow_0_6, (x->>'time_of_day') IS NOT NULL AS has_time_of_day, (x->>'time') IS NOT NULL AS has_time, count(*) AS n_entries FROM e GROUP BY 1, 2, 3, 4")
N = " , s AS (SELECT c.user_id, (c.t_done AT TIME ZONE c.tz) AS lt, CASE WHEN left(btrim(coalesce(c.therapy_schedule,'')),1) = '[' THEN c.therapy_schedule::jsonb ELSE '[]'::jsonb END AS sj, CASE WHEN left(btrim(coalesce(c.custom_therapy_sessions,'')),1) = '[' THEN c.custom_therapy_sessions::jsonb ELSE '[]'::jsonb END AS cj FROM c WHERE POPFILTER), s2 AS (SELECT * FROM s WHERE jsonb_array_length(sj) > 0 OR jsonb_array_length(cj) > 0), cand AS (SELECT s2.user_id, CASE WHEN ((x->>'day_of_week')::int - (extract(isodow FROM s2.lt)::int - 1) + 7) % 7 = 0 AND coalesce(nullif(x->>'time_of_day',''), x->>'time', '00:00')::time <= s2.lt::time THEN 7 ELSE ((x->>'day_of_week')::int - (extract(isodow FROM s2.lt)::int - 1) + 7) % 7 END AS d FROM s2, jsonb_array_elements(s2.sj) x WHERE (x->>'day_of_week') ~ '^[0-6]$' AND coalesce(nullif(x->>'time_of_day',''), x->>'time', '00:00') ~ '^[0-9]{1,2}:[0-9]{2}' UNION ALL SELECT s2.user_id, ((x->>'date')::date - s2.lt::date) AS d FROM s2, jsonb_array_elements(s2.cj) x WHERE (x->>'date') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' AND CASE WHEN (x->>'date') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' AND coalesce(nullif(x->>'time_of_day',''), '23:59') ~ '^[0-9]{1,2}:[0-9]{2}$' THEN ((x->>'date')::date + coalesce(nullif(x->>'time_of_day',''), '23:59')::time) > s2.lt ELSE false END), nx AS (SELECT s2.user_id, min(cand.d) AS d FROM s2 LEFT JOIN cand ON cand.user_id = s2.user_id GROUP BY s2.user_id)"
P_IN = "c.cit IN ('yes_regular','yes_occasional')"
P_ALL = "true"
_ = [q(f"q4_days_to_next_{lab}_{d}", cohort(d) + N.replace("POPFILTER", pf) + " SELECT CASE WHEN d IS NULL THEN 'none_future' WHEN d > 7 THEN 'gt7' ELSE lpad(d::text, 2, '0') END AS days_to_next, count(*) AS u_users FROM nx GROUP BY 1 ORDER BY 1") for d in (90, 30) for lab, pf in (("in_therapy", P_IN), ("all_with_sched", P_ALL))]
_ = [q(f"q4_days_to_next_median_{lab}_{d}", cohort(d) + N.replace("POPFILTER", pf) + " SELECT count(*) AS u_with_sched, count(d) AS u_with_future, percentile_cont(0.5) WITHIN GROUP (ORDER BY d) AS median_days FROM nx") for d in (90, 30) for lab, pf in (("in_therapy", P_IN), ("all_with_sched", P_ALL))]
_ = [q(f"q5_goals_text_{d}", cohort(d) + " SELECT count(*) AS u_cohort, count(*) FILTER (WHERE goals_text IS NOT NULL AND length(btrim(goals_text)) > 0) AS u_goals_text FROM c") for d in (90, 30)]
_ = [q(f"q5_xcheck_user_goals_{d}", cohort(d) + " SELECT count(*) AS u_cohort, count(*) FILTER (WHERE EXISTS (SELECT 1 FROM user_goals g WHERE g.user_id = c.user_id AND g.created_at >= c.t_start - interval '1 minute' AND g.created_at <= c.t_done + interval '1 hour')) AS u_goal_rows_at_onboarding FROM c") for d in (90, 30)]
_ = [q(f"q6_fcm_{d}", cohort(d) + " , f AS (SELECT user_id, min(created_at) AS first_tok FROM user_fcm_token WHERE user_id IN (SELECT user_id FROM c) GROUP BY user_id) SELECT count(*) AS u_cohort, count(f.user_id) AS u_fcm_any, count(f.user_id) FILTER (WHERE f.first_tok <= c.t_done + interval '1 day') AS u_fcm_oldest_surviving_within_1d FROM c LEFT JOIN f ON f.user_id = c.user_id") for d in (90, 30)]
_ = [q(f"q7_tz_validity_{d}", cohort(d) + " SELECT tz_valid, (tz = 'UTC') AS resolved_utc, count(*) AS u_users FROM c GROUP BY 1, 2 ORDER BY 1, 2") for d in (90, 30)]
_ = [q(f"q7_local_hour_3h_{d}", cohort(d) + " SELECT lpad(((floor(extract(hour FROM (t_done AT TIME ZONE tz)) / 3) * 3)::int)::text, 2, '0') AS local_hour_bucket, count(*) AS u_users FROM c GROUP BY 1 ORDER BY 1") for d in (90, 30)]
_ = [q(f"q7_utc_hour_3h_{d}", cohort(d) + " SELECT lpad(((floor(extract(hour FROM (t_done AT TIME ZONE 'UTC')) / 3) * 3)::int)::text, 2, '0') AS utc_hour_bucket, count(*) AS u_users FROM c GROUP BY 1 ORDER BY 1") for d in (90, 30)]
W = "o.t_start - interval '1 minute' AND XX.created_at <= o.t_done + interval '7 days'"
M = cohort(30) + " , o AS (SELECT c.user_id, c.t_start, c.t_done, (SELECT min(s.created_at) FROM symptom_scores s WHERE s.user_id = c.user_id AND s.created_at >= c.t_start - interval '1 minute') AS ob_score_at FROM c), m AS (SELECT o.user_id, (o.t_done <= now() - interval '7 days') AS full_window, EXISTS (SELECT 1 FROM symptom_scores s WHERE s.user_id = o.user_id AND s.created_at > coalesce(o.ob_score_at + interval '5 minutes', o.t_done) AND s.created_at <= o.t_done + interval '7 days') AS score_after, EXISTS (SELECT 1 FROM conversations v WHERE v.user_id = o.user_id AND v.conversation_type::text = 'REFLECT' AND v.last_message_at IS NOT NULL AND v.created_at >= " + W.replace("XX", "v") + ") AS reflect_any, EXISTS (SELECT 1 FROM conversations v WHERE v.user_id = o.user_id AND v.conversation_type::text = 'REFLECT' AND v.last_message_at IS NOT NULL AND v.entry_origin IS DISTINCT FROM 'onboarding_first_conversation' AND v.created_at >= " + W.replace("XX", "v") + ") AS reflect_non_first, (SELECT count(*) FROM conversations v WHERE v.user_id = o.user_id AND v.conversation_type::text = 'REFLECT' AND v.last_message_at IS NOT NULL AND v.created_at >= " + W.replace("XX", "v") + ") AS reflect_n, EXISTS (SELECT 1 FROM conversations v WHERE v.user_id = o.user_id AND v.entry_origin = 'onboarding_first_conversation' AND v.created_at >= " + W.replace("XX", "v") + ") AS first_conv, EXISTS (SELECT 1 FROM session_debriefs x WHERE x.user_id = o.user_id AND x.created_at >= " + W.replace("XX", "x") + ") AS debrief, EXISTS (SELECT 1 FROM session_prep_cards x WHERE x.user_id = o.user_id AND coalesce(x.generation_type, 'manual') <> 'auto' AND upper(x.input_type::text) <> 'AUTO' AND x.created_at >= " + W.replace("XX", "x") + ") AS prep_user, EXISTS (SELECT 1 FROM session_prep_cards x WHERE x.user_id = o.user_id AND x.created_at >= " + W.replace("XX", "x") + ") AS prep_any, EXISTS (SELECT 1 FROM between_session_notes x WHERE x.user_id = o.user_id AND x.created_at >= " + W.replace("XX", "x") + ") AS bsn FROM o)"
q("q8_first_week_30", M + " SELECT full_window, count(*) AS u_cohort, count(*) FILTER (WHERE score_after) AS u_score_after, count(*) FILTER (WHERE reflect_any) AS u_reflect_any, count(*) FILTER (WHERE reflect_non_first) AS u_reflect_non_first, count(*) FILTER (WHERE reflect_n >= 2) AS u_reflect_2plus, count(*) FILTER (WHERE first_conv) AS u_first_conv, count(*) FILTER (WHERE debrief) AS u_debrief, count(*) FILTER (WHERE prep_user) AS u_prep_user, count(*) FILTER (WHERE prep_any) AS u_prep_any, count(*) FILTER (WHERE bsn) AS u_bsn, count(*) FILTER (WHERE debrief OR prep_user OR bsn) AS u_any_therapy_entry FROM m GROUP BY ROLLUP (full_window) ORDER BY 1")
q("q9_memory_global_by_source", "SELECT source, min(created_at)::date AS first_day, count(*) AS u_items, count(DISTINCT user_id) AS u_users FROM user_memory_items GROUP BY 1 ORDER BY 2")
MI = " , c2 AS (SELECT c.* FROM c WHERE SUBFILTER), mi AS (SELECT c2.user_id, count(i.id) AS n FROM c2 LEFT JOIN user_memory_items i ON i.user_id = c2.user_id AND i.created_at >= c2.t_start - interval '1 minute' AND i.created_at <= c2.t_done + interval '24 hours' GROUP BY c2.user_id)"
SUBS = (("all30", "true"), ("since_memory_launch", "c.t_done >= (SELECT min(created_at) FROM user_memory_items)"))
_ = [q(f"q9_memory_24h_stats_{lab}", cohort(30) + MI.replace("SUBFILTER", sf) + " SELECT count(*) AS u_cohort, count(*) FILTER (WHERE n > 0) AS u_with_items, percentile_cont(0.5) WITHIN GROUP (ORDER BY n) AS median_all, percentile_cont(0.5) WITHIN GROUP (ORDER BY n) FILTER (WHERE n > 0) AS median_nonzero FROM mi") for lab, sf in SUBS]
_ = [q(f"q9_memory_24h_dist_{lab}", cohort(30) + MI.replace("SUBFILTER", sf) + " SELECT CASE WHEN n = 0 THEN 'a_0' WHEN n <= 2 THEN 'b_1-2' WHEN n <= 5 THEN 'c_3-5' WHEN n <= 10 THEN 'd_6-10' ELSE 'e_11+' END AS items, count(*) AS u_users FROM mi GROUP BY 1 ORDER BY 1") for lab, sf in SUBS]
q("q9_memory_24h_categories_30", cohort(30) + " SELECT i.category, count(*) AS u_items, count(DISTINCT i.user_id) AS u_users FROM c JOIN user_memory_items i ON i.user_id = c.user_id AND i.created_at >= c.t_start - interval '1 minute' AND i.created_at <= c.t_done + interval '24 hours' GROUP BY 1 ORDER BY 2 DESC")
q("q9_memory_24h_sources_30", cohort(30) + " SELECT i.source, count(*) AS u_items, count(DISTINCT i.user_id) AS u_users FROM c JOIN user_memory_items i ON i.user_id = c.user_id AND i.created_at >= c.t_start - interval '1 minute' AND i.created_at <= c.t_done + interval '24 hours' GROUP BY 1 ORDER BY 2 DESC")
db.rollback()
db.close()
print("DONE_SENTINEL")
